let language=localStorage.getItem('js-lang')||'en', theme=localStorage.getItem('js-theme')||'dark', docs=[], currentDoc=null, selectedFile=null, view='history', toastTimer, maxUploadBytes=20*1024*1024, guestId=localStorage.getItem('js-guest-id');if(!guestId){guestId=crypto.randomUUID();localStorage.setItem('js-guest-id',guestId)}
function translate(){document.documentElement.lang=language;document.querySelectorAll('[data-i]').forEach(e=>{const v=words[language][e.dataset.i];if(v)e.innerHTML=v});document.querySelectorAll('[data-ph]').forEach(e=>{const v=words[language][e.dataset.ph];if(v)e.placeholder=v})}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
async function api(url,options={}){const timeoutMs=options.timeoutMs||45000,controller=new AbortController();delete options.timeoutMs;options.headers={...(options.headers||{}),'X-Guest-Id':guestId};options.signal=controller.signal;const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const res=await fetch(url,options);if(!res.ok){let body={};try{body=await res.json()}catch{}throw Error(body.detail||`Request failed (${res.status})`)}return res.status===204?null:res.json()}catch(error){if(error.name==='AbortError')throw Error('Request timed out. Please try again.');if(error instanceof TypeError)throw Error('Network error. Check your connection and try again.');throw error}finally{clearTimeout(timer)}}
api('/api/health').then(data=>{if(Number.isFinite(data.max_upload_bytes)&&data.max_upload_bytes>0){maxUploadBytes=data.max_upload_bytes;translate();updateUploadLimitLabel()}}).catch(error=>console.warn('Could not read JanSathi API configuration:',error.message));
function openApp(next='history'){stopScanner();document.querySelector('.landing').classList.add('hidden');$('#workspace').classList.remove('hidden');$('#float-chat').classList.remove('hidden');setView(next);loadDocs()}
function home(){stopScanner();document.querySelector('.landing').classList.remove('hidden');$('#workspace').classList.add('hidden');$('#float-chat').classList.add('hidden');history.replaceState(null,'','#home')}
function setView(name){view=name;$$('.side-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={history:words[language].history,pdfs:words[language].myPdfs,chat:words[language].askJan};$('#view-title').textContent=titles[name];$('#view-crumb').textContent=titles[name].toUpperCase();renderView()}
async function loadDocs(){try{docs=await api('/api/documents');$('#doc-count').textContent=docs.length;renderView()}catch(e){showToast(e.message)}}
const dateFmt=s=>{try{return new Intl.DateTimeFormat(language==='en'?'en-IN':language==='hi'?'hi-IN':'gu-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s))}catch{return s}};
function renderView(){const host=$('#view-content');if(view==='chat'){renderChat(host);return}const pdfOnly=view==='pdfs';const q=$('#search').value.toLowerCase();const list=docs.filter(d=>(!pdfOnly||d.file_type==='PDF')&&d.title.toLowerCase().includes(q));if(!list.length){host.innerHTML=`<div class="empty-state"><div class="empty-art">＋</div><h2>${pdfOnly?'Your PDF library is ready':'Your document space is ready'}</h2><p>${pdfOnly?'PDFs you upload will appear here, ready to revisit whenever you need.':'Start with a notice, letter or policy. JanSathi will help make the important parts clear.'}</p><button class="button button-primary" id="empty-upload">＋ ${words[language].upload}</button></div>`;$('#empty-upload').onclick=openDocumentActions;return}host.innerHTML=`<div class="view-toolbar"><p>${list.length} ${list.length===1?'document':'documents'} · Private workspace</p><div class="filters"><button class="filter-btn selected">All files</button><button class="filter-btn" id="sort-btn">Recently added ↓</button></div></div><div class="document-table"><div class="table-head"><span>DOCUMENT</span><span>TYPE</span><span>ADDED</span><span>STATUS</span><span></span></div>${list.map(d=>`<div class="doc-row"><div class="doc-name"><span class="file-type-icon ${d.file_type.toLowerCase()}">${d.file_type==='DOCX'?'DOC':d.file_type}</span><span><button class="doc-title" data-open="${d.id}">${escapeHtml(d.title)}</button><small>${formatBytes(d.size)}</small></span></div><span>${d.file_type}</span><span>${dateFmt(d.created_at)}</span><span class="status-pill">${d.status==='completed'?'Ready':d.status==='needs_ocr'?'Needs OCR':'No text'}</span><button class="row-menu" data-delete="${d.id}" aria-label="Delete document">···</button></div>`).join('')}</div>`;host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));host.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteDoc(b.dataset.delete));$('#sort-btn').onclick=()=>{docs.reverse();renderView()}}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function formatBytes(n){if(n<1024)return n+' B';return (n/1024/1024<1?(n/1024).toFixed(0)+' KB':(n/1024/1024).toFixed(1)+' MB')}
async function deleteDoc(id){if(!confirm('Delete this document and its stored file?'))return;try{await api('/api/documents/'+id,{method:'DELETE'});if(currentDoc===id)currentDoc=null;showToast('Document deleted.');await loadDocs()}catch(e){showToast(e.message)}}
async function openDetail(id){try{const d=await api('/api/documents/'+id);currentDoc=id;$('#detail-icon').textContent=d.file_type;$('#detail-icon').className='file-type-icon '+d.file_type.toLowerCase();$('#detail-title').textContent=d.title;$('#detail-meta').textContent=`${d.file_type} · ${dateFmt(d.created_at)} · ${formatBytes(d.size)}`;$('#detail-text').textContent=d.overview;$('#detail-download').onclick=async e=>{e.preventDefault();try{const r=await fetch('/api/documents/'+id+'/file',{headers:{'X-Guest-Id':guestId}});if(!r.ok)throw Error('Could not open this file.');const u=URL.createObjectURL(await r.blob());window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(err){showToast(err.message)}};$('#detail-ask').onclick=()=>{closeModal('detail-modal');currentDoc=d.id;openApp('chat');renderChat($('#view-content'),d.id)};$('#detail-modal').classList.remove('hidden')}catch(e){showToast(e.message)}}
function openUpload(){selectedFile=null;$('#file-input').value='';$('#selected-file').classList.add('hidden');$('#process-file').disabled=true;$('#process-file').classList.remove('hidden');$('#processing').classList.add('hidden');$('#upload-modal').classList.remove('hidden')}
function selectFile(file){if(!file)return;const allowed=['.pdf','.txt','.docx','.png','.jpg','.jpeg'];const ext='.'+file.name.split('.').pop().toLowerCase();if(!allowed.includes(ext)){showToast('Please choose PDF, TXT, DOCX, PNG or JPG.');return}if(file.size>20*1024*1024){showToast('Files must be 20 MB or smaller.');return}selectedFile=file;$('#selected-file').textContent=`✓ ${file.name} · ${formatBytes(file.size)}`;$('#selected-file').classList.remove('hidden');$('#process-file').disabled=false}
async function upload(){if(!selectedFile)return;$('#process-file').classList.add('hidden');$('#processing').classList.remove('hidden');const stages=['Uploading your file…','Checking file and extracting text…','Preparing your overview…'];let i=0;$('#processing-title').textContent=stages[0];const ticker=setInterval(()=>{$('#processing-title').textContent=stages[Math.min(++i,stages.length-1)]},850);try{const data=new FormData();data.append('file',selectedFile);const d=await api('/api/documents',{method:'POST',body:data});clearInterval(ticker);closeModal('upload-modal');currentDoc=d.id;openApp('history');showToast(d.status==='completed'?'Document ready.':'File saved. OCR is needed to read its text.');openDetail(d.id)}catch(e){clearInterval(ticker);$('#processing').classList.add('hidden');$('#process-file').classList.remove('hidden');showToast(e.message)}}
function closeModal(id){$('#'+id).classList.add('hidden')}
function renderChat(host,docId=currentDoc){host.innerHTML=`<div class="chat-layout"><section class="chat-main"><div class="chat-messages" id="messages"><div class="message"><span class="message-avatar">✳</span><div class="message-bubble">${docId?'I’m ready to help you understand this document. Ask me about a deadline, requirement or section.':'Hello! I can help explain public information or answer questions about a document you’ve uploaded. What would you like to know?'}</div></div></div><form class="chat-compose" id="chat-form"><textarea id="chat-input" rows="1" placeholder="${language==='hi'?'अपना सवाल लिखें…':language==='gu'?'તમારો પ્રશ્ન લખો…':'Ask a question…'}"></textarea><button class="button button-primary" type="submit">Send <span>↗</span></button></form></section><aside class="chat-aside"><h3>Ask with confidence</h3><p>Answers are generated from your document when one is selected. Verify important deadlines and eligibility with the issuing agency.</p>${docId?`<span class="context-chip">▤ ${escapeHtml(docs.find(x=>x.id===docId)?.title||'Selected document')}</span>`:''}<h3 style="margin-top:20px">Try asking</h3><button class="suggestion">What is this document asking me to do?</button><button class="suggestion">Are there any important dates?</button><button class="suggestion">Explain this in simpler words</button></aside></div>`;const form=$('#chat-form'),input=$('#chat-input'),messages=$('#messages');host.querySelectorAll('.suggestion').forEach(b=>b.onclick=()=>{input.value=b.textContent;form.requestSubmit()});form.onsubmit=async ev=>{ev.preventDefault();const message=input.value.trim();if(!message)return;appendMessage(messages,message,true);input.value='';const wait=appendMessage(messages,'Thinking…',false);try{const result=await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,document_id:docId,language})});wait.querySelector('.message-bubble').textContent=result.answer;messages.scrollTop=messages.scrollHeight}catch(e){wait.querySelector('.message-bubble').textContent=e.message}};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}}}
function appendMessage(parent,text,user){const div=document.createElement('div');div.className='message'+(user?' user':'');const avatar=document.createElement('span');avatar.className='message-avatar';avatar.textContent=user?'J':'✳';const bubble=document.createElement('div');bubble.className='message-bubble';bubble.textContent=text;div.append(avatar,bubble);parent.append(div);parent.scrollTop=parent.scrollHeight;return div}
$('#language').value=language;$('#language').onchange=e=>{language=e.target.value;localStorage.setItem('js-lang',language);translate();if(!$('#workspace').classList.contains('hidden'))setView(view)};document.body.classList.toggle('light',theme==='light');$('#theme').textContent=theme==='light'?'☾':'☼';$('#theme').onclick=()=>{theme=theme==='light'?'dark':'light';document.body.classList.toggle('light',theme==='light');$('#theme').textContent=theme==='light'?'☾':'☼';localStorage.setItem('js-theme',theme)};translate();
$('#open-app').onclick=()=>openApp();$('#hero-upload').onclick=()=>{openApp();openDocumentActions()};$('#new-doc').onclick=$('#top-upload').onclick=openDocumentActions;$('#try-chat').onclick=()=>openApp('chat');$('#brand').onclick=e=>{e.preventDefault();home()};$('#home-link').onclick=e=>{e.preventDefault();home()};$('#float-chat').onclick=()=>{openApp('chat');renderChat($('#view-content'))};$$('.side-link[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#file-input').onchange=e=>selectFile(e.target.files[0]);$('#process-file').onclick=upload;const dz=$('#dropzone');dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');selectFile(e.dataTransfer.files[0])};$$('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));$$('.modal-backdrop').forEach(b=>b.onclick=e=>{if(e.target===b)closeModal(b.id)});$('#search').oninput=()=>renderView();$('#settings').onclick=()=>showToast('Theme and language preferences are saved on this device.');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$$('.modal-backdrop').forEach(m=>m.classList.add('hidden'))});

