let sortMode='newest',typeMode='all',uploadBusy=false,profileData={first_name:'',last_name:'',email:null},focusReturn=null,modalTimers=new Map(),chatThreads={};
function updateUploadLimitLabel(){const node=$('#supported');if(node)node.textContent=node.textContent.replace(/[\d.]+\s*MB/,`${(maxUploadBytes/(1024*1024)).toLocaleString(language,{maximumFractionDigits:2})} MB`)}
function selectFile(file){if(!file)return;const ext='.'+file.name.split('.').pop().toLowerCase(),allowed=['.pdf','.txt','.docx','.png','.jpg','.jpeg'];if(!allowed.includes(ext)){showToast('Choose PDF, TXT, DOCX, PNG or JPG.');return}if(file.size>maxUploadBytes){showToast(`Files must be ${(maxUploadBytes/(1024*1024)).toLocaleString(language,{maximumFractionDigits:2})} MB or smaller.`);return}selectedFile=file;$('#selected-file').textContent=`${ext.slice(1).toUpperCase()} · ${file.name} · ${formatBytes(file.size)}`;$('#selected-file').classList.remove('hidden');$('#remove-file').textContent=words[language].removeFile;$('#remove-file').classList.remove('hidden');$('#dropzone').classList.add('has-file');$('#process-file').disabled=false}

function openModal(id){const node=$('#'+id);if(!node)return;clearTimeout(modalTimers.get(id));focusReturn=document.activeElement;document.body.classList.add('modal-open');node.classList.remove('hidden','closing');requestAnimationFrame(()=>node.querySelector('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')?.focus())}
function closeModal(id){const node=$('#'+id);if(!node||node.classList.contains('hidden'))return;if(id==='scanner-modal')scannerController.close();node.classList.add('closing');clearTimeout(modalTimers.get(id));modalTimers.set(id,setTimeout(()=>{node.classList.add('hidden');node.classList.remove('closing');if(!document.querySelector('.modal-backdrop:not(.hidden):not(.closing)'))document.body.classList.remove('modal-open');focusReturn?.focus?.()},180))}
function modalKeys(e){if(typeof e.target?.closest!=='function')return;const dialog=e.target.closest('.modal-backdrop:not(.hidden)');if(!dialog)return;if(e.key==='Escape'){e.preventDefault();closeModal(dialog.id);return}if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href],textarea:not([disabled])')].filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
document.addEventListener('keydown',modalKeys);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const visible=document.querySelector('.modal-backdrop:not(.hidden)');if(visible){e.preventDefault();e.stopImmediatePropagation();closeModal(visible.id)}}},true);
$$('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));$$('.modal-backdrop').forEach(b=>b.addEventListener('click',e=>{if(e.target===b)closeModal(b.id)}));

function openUpload(){selectedFile=null;uploadBusy=false;$('#file-input').value='';$('#selected-file').textContent='';$('#selected-file').classList.add('hidden');$('#remove-file').classList.add('hidden');$('#dropzone').classList.remove('has-file','drag');$('#process-file').disabled=true;$('#process-file').classList.remove('hidden','is-loading');$('#processing').classList.add('hidden');$('#processing-title').textContent='';$('#processing-sub').textContent='';openModal('upload-modal')}
function openDocumentActions(){if(matchMedia('(max-width: 720px)').matches)openModal('mobile-actions-modal');else openUpload()}
function scannerState(state){const preview=['preview','uploading','upload-error','uploaded'].includes(state.phase);$('#scanner-error').textContent=state.error||'';$('#scanner-error').classList.toggle('hidden',!state.error);$('#scanner-video').classList.toggle('hidden',preview||state.phase==='error'||state.phase==='closed');$('#scanner-preview').classList.toggle('hidden',!preview);$('#scanner-preview').src=preview?state.previewUrl:'';$('#scanner-empty').classList.toggle('hidden',state.phase!=='error');$('#scanner-capture').classList.toggle('hidden',state.phase!=='live');$('#scanner-retake').classList.toggle('hidden',!['preview','upload-error'].includes(state.phase));$('#scanner-confirm').classList.toggle('hidden',state.phase!=='preview'||state.autoCaptured);$('#scanner-retry-upload').classList.toggle('hidden',state.phase!=='upload-error');$('#scanner-fallback').classList.toggle('hidden',state.phase!=='error');$('#scanner-auto-capture').checked=state.autoCapture!==false;$('#scanner-auto-capture').disabled=!['live','requesting'].includes(state.phase);$('#scanner-status').textContent=state.status||'Looking for document...';$('#scanner-status').classList.toggle('hidden',!['live','requesting','uploading','uploaded'].includes(state.phase));const progress=$('#scanner-upload-progress');progress.classList.toggle('hidden',state.phase!=='uploading');progress.value=state.uploadProgress||0;if(state.phase==='requesting')$('#scanner-description').textContent=words[language].cameraRequest;else if(state.phase==='live')$('#scanner-description').textContent=words[language].scanHint;else if(preview&&state.phase!=='uploading')$('#scanner-description').textContent=words[language].reviewPhoto;else if(state.phase==='closed')$('#scanner-description').textContent=words[language].scanHint}
function uploadScannedFile(file,{signal,onProgress}){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),form=new FormData();form.append('file',file);xhr.open('POST','/api/documents');xhr.setRequestHeader('X-Guest-Id',guestId);xhr.timeout=110000;const abort=()=>xhr.abort();if(signal.aborted){reject(Error('Upload cancelled.'));return}signal.addEventListener('abort',abort,{once:true});const cleanup=()=>signal.removeEventListener('abort',abort);xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(Math.round(e.loaded/e.total*100))};xhr.onload=()=>{cleanup();let result;try{result=JSON.parse(xhr.responseText)}catch{}if(xhr.status<200||xhr.status>=300||!result?.id){reject(Error(result?.detail||`Upload failed (${xhr.status}). Retry or retake the photo.`));return}resolve(result)};xhr.onerror=()=>{cleanup();reject(Error('Network error during upload. Retry the captured photo.'))};xhr.ontimeout=()=>{cleanup();reject(Error('Upload timed out. Retry the captured photo.'))};xhr.onabort=()=>{cleanup();reject(Error('Upload cancelled.'))};xhr.send(form)})}
function scannerUploadComplete(doc){closeModal('scanner-modal');currentDoc=doc.id;openApp('history');showToast(doc.status==='completed'?'Document ready.':'File saved, but readable text was not found.');void openDetail(doc.id)}
const scannerController=window.JanSathiScanner.createScannerController({video:$('#scanner-video'),canvas:$('#scanner-canvas'),analysisCanvas:$('#scanner-analysis-canvas'),onState:scannerState,onAutoUpload:uploadScannedFile,onAutoUploadComplete:scannerUploadComplete,onConfirm:file=>{const backdrop=$('#scanner-modal');backdrop.classList.add('hidden');backdrop.classList.remove('closing');openUpload();selectFile(file)}});
function stopScanner(){scannerController.close();$('#scanner-modal').classList.add('hidden');$('#scanner-modal').classList.remove('closing')}
function openScanner(){ $('#mobile-actions-modal').classList.add('hidden');$('#mobile-actions-modal').classList.remove('closing');$('#scanner-file-input').value='';openModal('scanner-modal');void scannerController.start() }
$('#mobile-action-upload').onclick=()=>{closeModal('mobile-actions-modal');openUpload()};$('#mobile-action-scan').onclick=openScanner;$('#scanner-auto-capture').onchange=e=>scannerController.setAutoCapture(e.target.checked);$('#scanner-capture').onclick=()=>{void scannerController.capture()};$('#scanner-retake').onclick=()=>{void scannerController.start()};$('#scanner-confirm').onclick=()=>scannerController.confirm();$('#scanner-retry-upload').onclick=()=>{void scannerController.retryUpload()};$('#scanner-cancel').onclick=()=>closeModal('scanner-modal');$('#scanner-fallback').onclick=()=>$('#scanner-file-input').click();$('#scanner-file-input').onchange=e=>{const file=e.target.files?.[0];if(file&&!scannerController.usePhoto(file))showToast('Choose a JPG or PNG image.');e.target.value=''};window.addEventListener('pagehide',()=>scannerController.dispose());document.addEventListener('visibilitychange',()=>{if(document.hidden&&!$('#scanner-modal').classList.contains('hidden')){scannerController.close();scannerState({phase:'error',error:'Camera stopped while the page was in the background. Reopen the scanner to continue.'})}});
function selectFile(file){if(!file)return;const ext='.'+file.name.split('.').pop().toLowerCase(),allowed=['.pdf','.txt','.docx','.png','.jpg','.jpeg'];if(!allowed.includes(ext)){showToast('Choose PDF, TXT, DOCX, PNG or JPG.');return}if(file.size>20*1024*1024){showToast('Files must be 20 MB or smaller.');return}selectedFile=file;$('#selected-file').textContent=`${ext.slice(1).toUpperCase()}  ·  ${file.name}  ·  ${formatBytes(file.size)}`;$('#selected-file').classList.remove('hidden');$('#remove-file').textContent=words[language].removeFile;$('#remove-file').classList.remove('hidden');$('#dropzone').classList.add('has-file');$('#process-file').disabled=false}
function removeSelectedFile(e){e?.preventDefault();e?.stopPropagation();selectedFile=null;$('#file-input').value='';$('#selected-file').textContent='';$('#selected-file').classList.add('hidden');$('#remove-file').classList.add('hidden');$('#dropzone').classList.remove('has-file');$('#process-file').disabled=true;$('#dropzone').focus()}
$('#remove-file').onclick=removeSelectedFile;$('#file-input').onchange=e=>selectFile(e.target.files[0]);$('#dropzone').onclick=e=>{if(e.target.closest('#remove-file'))return;$('#file-input').click()};$('#dropzone').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#file-input').click()}};$('#dropzone').ondragover=e=>{e.preventDefault();$('#dropzone').classList.add('drag')};$('#dropzone').ondragleave=e=>{if(!$('#dropzone').contains(e.relatedTarget))$('#dropzone').classList.remove('drag')};$('#dropzone').ondrop=e=>{e.preventDefault();$('#dropzone').classList.remove('drag');selectFile(e.dataTransfer.files[0])};
function upload(){if(!selectedFile||uploadBusy)return;uploadBusy=true;const button=$("#process-file"),processing=$("#processing"),retry=$("#retry-upload");button.disabled=true;button.classList.add("is-loading");retry.classList.add("hidden");processing.classList.remove("hidden");$("#processing-title").textContent="Uploading your document…";$("#processing-sub").textContent="0% uploaded";const xhr=new XMLHttpRequest(),form=new FormData();form.append("file",selectedFile);xhr.open("POST","/api/documents");xhr.setRequestHeader("X-Guest-Id",guestId);xhr.timeout=100000;xhr.upload.onprogress=e=>{if(e.lengthComputable){const pct=Math.round(e.loaded/e.total*100);$("#processing-title").textContent=pct<100?"Uploading your document…":"Extracting document content…";$("#processing-sub").textContent=pct<100?`${pct}% uploaded`:"Upload complete · waiting for document processing"}};function reset(){uploadBusy=false;button.disabled=false;button.classList.remove("is-loading");processing.classList.add("hidden");button.classList.remove("hidden")};xhr.onload=()=>{reset();let d;try{d=JSON.parse(xhr.responseText)}catch{}if(xhr.status<200||xhr.status>=300||!d||!d.id){processing.classList.remove("hidden");button.classList.add("hidden");$("#processing-title").textContent="Upload failed";$("#processing-sub").textContent="";retry.classList.remove("hidden");showToast(d?.detail||"Upload failed. Check the file and try again.");return}$("#processing-title").textContent=d.status==="completed"?"Your document is ready":"Document saved · text extraction needs attention";$("#processing-sub").textContent="Opening your document overview…";setTimeout(()=>{closeModal("upload-modal");currentDoc=d.id;openApp("history");showToast(d.status==="completed"?"Document ready.":"File saved, but readable text was not found.");openDetail(d.id)},220)};xhr.onerror=()=>{reset();processing.classList.remove("hidden");button.classList.add("hidden");$("#processing-title").textContent="Upload failed";$("#processing-sub").textContent="";retry.classList.remove("hidden");showToast("Network error. Your document was not uploaded.")};xhr.ontimeout=()=>{reset();processing.classList.remove("hidden");button.classList.add("hidden");$("#processing-title").textContent="Upload timed out";$("#processing-sub").textContent="";retry.classList.remove("hidden");showToast("The upload took too long. Please try again.")};xhr.onabort=()=>{reset();showToast("Upload cancelled.")};xhr.send(form);retry.onclick=()=>{retry.classList.add("hidden");upload();}}
$('#process-file').onclick=upload;

function renderView(){const host=$('#view-content');if(view==='chat'){renderChat(host);return}const q=$('#search').value.toLowerCase();let list=docs.filter(d=>(view!=='pdfs'||d.file_type==='PDF')&&d.title.toLowerCase().includes(q));if(typeMode!=='all')list=list.filter(d=>d.file_type===typeMode);list=[...list].sort((a,b)=>sortMode==='oldest'?new Date(a.created_at)-new Date(b.created_at):sortMode==='name'?a.title.localeCompare(b.title):new Date(b.created_at)-new Date(a.created_at));if(!list.length){host.innerHTML=`<div class="empty-state"><div class="empty-art">＋</div><h2>${view==='pdfs'?'Your PDF library is ready':'Your document space is ready'}</h2><p>${view==='pdfs'?'PDFs you upload will appear here, ready to revisit whenever you need.':'Start with a notice, letter or policy. JanSathi will help make the important parts clear.'}</p><button class="button button-primary" id="empty-upload">＋ ${words[language].upload}</button></div>`;$('#empty-upload').onclick=openDocumentActions;return}host.innerHTML=`<div class="view-toolbar"><p>${list.length} ${list.length===1?'document':'documents'} · Private workspace</p><div class="filters"><label class="sr-only" for="type-filter">Filter document type</label><select id="type-filter" class="menu-select"><option value="all">${words[language].allFiles}</option>${['PDF','TXT','DOCX','PNG','JPG','JPEG'].filter(t=>view==='history'||t==='PDF').map(t=>`<option value="${t}">${t}</option>`).join('')}</select><label class="sr-only" for="sort-filter">Sort documents</label><select id="sort-filter" class="menu-select"><option value="newest">${words[language].newest}</option><option value="oldest">${words[language].oldest}</option><option value="name">${words[language].nameAZ}</option></select></div></div><div class="document-table"><div class="table-head"><span>DOCUMENT</span><span>TYPE</span><span>ADDED</span><span>STATUS</span><span></span></div>${list.map(d=>`<div class="doc-row"><div class="doc-name"><span class="file-type-icon ${d.file_type.toLowerCase()}">${d.file_type==='DOCX'?'DOC':d.file_type}</span><span><button class="doc-title" data-open="${d.id}">${escapeHtml(d.title)}</button><small>${formatBytes(d.size)}</small></span></div><span>${d.file_type}</span><span>${dateFmt(d.created_at)}</span><span class="status-pill ${d.status==='completed'?'':'status-needs'}">${d.status==='completed'?'Ready':d.status==='needs_ocr'?'Needs OCR':'No text'}</span><div class="row-menu-wrap"><button class="row-menu" data-menu="${d.id}" aria-label="Actions for ${escapeHtml(d.title)}" aria-haspopup="menu" aria-expanded="false">···</button><div class="doc-menu hidden" role="menu" data-doc-menu="${d.id}"><button role="menuitem" data-action="view" data-id="${d.id}">${words[language].viewDocument}</button><button role="menuitem" data-action="ask" data-id="${d.id}">${words[language].askDocument}</button><button role="menuitem" class="danger-text" data-action="delete" data-id="${d.id}">${words[language].deleteDocument}</button></div></div></div>`).join('')}</div>`;$('#type-filter').value=typeMode;$('#sort-filter').value=sortMode;$('#type-filter').onchange=e=>{typeMode=e.target.value;renderView()};$('#sort-filter').onchange=e=>{sortMode=e.target.value;renderView()};host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));host.querySelectorAll('[data-menu]').forEach(b=>b.onclick=e=>{e.stopPropagation();const menu=host.querySelector(`[data-doc-menu="${b.dataset.menu}"]`),open=menu.classList.contains('hidden');host.querySelectorAll('.doc-menu').forEach(m=>m.classList.add('hidden'));host.querySelectorAll('[data-menu]').forEach(x=>x.setAttribute('aria-expanded','false'));menu.classList.toggle('hidden',!open);b.setAttribute('aria-expanded',String(open))});host.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const id=b.dataset.id,action=b.dataset.action;if(action==='view')openDetail(id);if(action==='ask'){currentDoc=id;openApp('chat');renderChat($('#view-content'),id)}if(action==='delete')confirmDelete(id)});}
document.addEventListener('click',e=>{if(!e.target.closest?.('.row-menu-wrap'))document.querySelectorAll('.doc-menu').forEach(m=>m.classList.add('hidden'))});
$('#search').oninput=()=>renderView();

let pendingDelete=null;function confirmDelete(id){pendingDelete=id;$('#confirm-title').textContent=words[language].deleteTitle;$('#confirm-copy').textContent=words[language].deleteBody;$('#confirm-cancel').textContent=words[language].cancel;$('#confirm-delete').textContent=words[language].deleteDocument;$('#confirm-delete').disabled=false;openModal('confirm-modal')}
$('#confirm-cancel').onclick=()=>{pendingDelete=null;closeModal('confirm-modal')};$('#confirm-delete').onclick=async()=>{if(!pendingDelete)return;const id=pendingDelete,btn=$('#confirm-delete');btn.disabled=true;btn.textContent=words[language].deleting;try{await api('/api/documents/'+id,{method:'DELETE'});docs=docs.filter(d=>d.id!==id);$('#doc-count').textContent=docs.length;if(currentDoc===id)currentDoc=null;closeModal('confirm-modal');closeModal('detail-modal');renderView();showToast(words[language].deleteSuccess)}catch(e){btn.disabled=false;btn.textContent=words[language].deleteDocument;showToast(e.message)}};
async function deleteDoc(id){confirmDelete(id)}

async function loadProfile(){try{profileData=await api('/api/profile');if(!profileData.has_profile){profileData.language=language;profileData.theme=theme}$('#profile-first').value=profileData.first_name||'';$('#profile-last').value=profileData.last_name||'';$('#profile-email').value=profileData.email||'';$('#profile-language').value=localStorage.getItem('js-lang')||profileData.language||language;$('#profile-theme').value=localStorage.getItem('js-theme')||profileData.theme||theme;updateProfileIdentity()}catch(e){$('#profile-error').textContent=e.message}}
function updateProfileIdentity(){const full=[profileData.first_name,profileData.last_name].filter(Boolean).join(' ');$('#profile-display-name').textContent=full||'Guest session';$('#profile-display-sub').textContent=full?'Guest profile':'Personal workspace';const initial=full?full.slice(0,1).toUpperCase():'J';$('.profile-avatar').textContent=initial}
$('#profile-open').onclick=async()=>{await loadProfile();openModal('profile-modal')};$('#profile-form').onsubmit=async e=>{e.preventDefault();const btn=$('#profile-save'),error=$('#profile-error');error.textContent='';const data={first_name:$('#profile-first').value.trim(),last_name:$('#profile-last').value.trim(),language:$('#profile-language').value,theme:$('#profile-theme').value};if(data.first_name.length>60||data.last_name.length>60){error.textContent='Names must be 60 characters or fewer.';return}btn.disabled=true;btn.classList.add('is-loading');try{profileData=await api('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});updateProfileIdentity();language=data.language;theme=data.theme;localStorage.setItem('js-lang',language);localStorage.setItem('js-theme',theme);$('#language').value=language;document.body.classList.toggle('light',theme==='light');$('#theme').textContent=theme==='light'?'☾':'☼';translate();showToast(words[language].saved);closeModal('profile-modal')}catch(err){error.textContent=err.message}finally{btn.disabled=false;btn.classList.remove('is-loading')}};

function detailDownloadHandler(id){$('#detail-download').onclick=async e=>{e.preventDefault();try{const r=await fetch('/api/documents/'+id+'/file',{headers:{'X-Guest-Id':guestId}});if(!r.ok)throw Error('Could not open this file.');const u=URL.createObjectURL(await r.blob());const win=window.open(u,'_blank','noopener');if(!win)showToast('Allow pop-ups to open this file.');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(err){showToast(err.message)}}}
async function openDetail(id){try{const d=await api('/api/documents/'+id);currentDoc=id;$('#detail-icon').textContent=d.file_type;$('#detail-icon').className='file-type-icon '+d.file_type.toLowerCase();$('#detail-title').textContent=d.title;$('#detail-meta').textContent=`${d.file_type} · ${dateFmt(d.created_at)} · ${formatBytes(d.size)}`;$('#detail-text').textContent=d.overview;detailDownloadHandler(id);$('#detail-ask').onclick=()=>{closeModal('detail-modal');currentDoc=d.id;openApp('chat');renderChat($('#view-content'),d.id)};openModal('detail-modal')}catch(e){showToast(e.message)}}

function renderChat(host,docId=currentDoc){const key=docId||'general';const thread=chatThreads[key]||(chatThreads[key]=[]);host.innerHTML=`<div class="chat-layout"><section class="chat-main"><header class="chat-header"><div class="chat-avatar">✳</div><div><b>JanSathi assistant</b><small>${docId?'Document-aware support':'Public information support'}</small></div>${docId?`<span class="context-chip">▤ ${escapeHtml(docs.find(x=>x.id===docId)?.title||'Selected document')}</span>`:''}<button type="button" class="chat-close" id="chat-close" aria-label="${words[language].chatClose}">×</button></header><div class="chat-messages" id="messages"></div><form class="chat-compose" id="chat-form"><textarea id="chat-input" rows="1" placeholder="${language==='hi'?'अपना सवाल लिखें…':language==='gu'?'તમારો પ્રશ્ન લખો…':'Ask a question…'}" aria-label="Ask JanSathi a question"></textarea><button class="button button-primary chat-send" type="submit" disabled aria-label="Send message">Send <span>↗</span></button></form></section><aside class="chat-aside"><h3>Ask with confidence</h3><p>Answers are generated from your document when one is selected. Verify important deadlines and eligibility with the issuing agency.</p><h3 style="margin-top:20px">Try asking</h3><button class="suggestion">What is this document asking me to do?</button><button class="suggestion">Are there any important dates?</button><button class="suggestion">Explain this in simpler words</button></aside></div>`;const messages=$('#messages');if(thread.length)thread.forEach(m=>appendMessage(messages,m.text,m.user,m));else appendMessage(messages,docId?'I’m ready to help you understand this document. Ask me about a deadline, requirement or section.':'Hello! I can help explain public information or answer questions about a document you’ve uploaded. What would you like to know?',false);$('#chat-close').onclick=()=>setView('history');const form=$('#chat-form'),input=$('#chat-input'),send=$('.chat-send');form.onsubmit=async ev=>{ev.preventDefault();const message=input.value.trim();if(!message||send.disabled)return;input.value='';thread.push({text:message,user:true});appendMessage(messages,message,true);send.disabled=true;input.disabled=true;const wait=appendMessage(messages,words[language].working,false,{pending:true});try{const result=await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,document_id:docId,language})});wait.remove();const answer={text:result.answer,user:false};thread.push(answer);appendMessage(messages,answer.text,false,answer)}catch(err){wait.remove();const failed=appendMessage(messages,err.message,false,{failed:true});const retry=document.createElement('button');retry.type='button';retry.className='message-retry';retry.textContent=words[language].retry;retry.onclick=()=>{thread.pop();input.value=message;form.requestSubmit()};failed.querySelector('.message-bubble').append(document.createElement('br'),retry)}finally{input.disabled=false;input.focus();send.disabled=!input.value.trim()}};input.oninput=()=>{send.disabled=!input.value.trim()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}};host.querySelectorAll('.suggestion').forEach(b=>b.onclick=()=>{input.value=b.textContent;send.disabled=false;form.requestSubmit()})}
function appendMessage(parent,text,user,meta={}){const div=document.createElement('div');div.className='message'+(user?' user':'')+(meta.pending?' pending':'');const avatar=document.createElement('span');avatar.className='message-avatar';avatar.textContent=user?'J':'✳';const bubble=document.createElement('div');bubble.className='message-bubble';bubble.textContent=text;div.append(avatar,bubble);if(!user&&!meta.pending&&!meta.failed){const actions=document.createElement('div');actions.className='message-actions';const copy=document.createElement('button');copy.type='button';copy.textContent='Copy';copy.setAttribute('aria-label','Copy answer');copy.onclick=async()=>{try{await navigator.clipboard.writeText(text);showToast('Answer copied.')}catch{showToast('Clipboard access is unavailable.')}};actions.append(copy);div.append(actions)}parent.append(div);if(typeof parent.scrollTo==='function')parent.scrollTo({top:parent.scrollHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});else parent.scrollTop=parent.scrollHeight;return div}
$('#float-chat').onclick=()=>{if(view==='chat'){setView('history')}else{openApp('chat');renderChat($('#view-content'))}};

