const motionOK=!matchMedia('(prefers-reduced-motion: reduce)').matches&&!matchMedia('(pointer: coarse)').matches;const heroVisual=$('.hero-visual');let pointerFrame=0;if(motionOK&&heroVisual){heroVisual.addEventListener('pointermove',e=>{if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{const r=heroVisual.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;heroVisual.style.setProperty('--pointer-x',`${x*100}%`);heroVisual.style.setProperty('--pointer-y',`${y*100}%`);$('.plus-core').style.setProperty('--tilt-x',`${(0.5-y)*5}deg`);$('.plus-core').style.setProperty('--tilt-y',`${(x-0.5)*5}deg`);pointerFrame=0})});heroVisual.addEventListener('pointerleave',()=>{$('.plus-core').style.setProperty('--tilt-x','0deg');$('.plus-core').style.setProperty('--tilt-y','0deg')});document.querySelectorAll('.hero-actions .button-primary').forEach(b=>{b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.setProperty('--mag-x',`${(e.clientX-r.left-r.width/2)*.045}px`);b.style.setProperty('--mag-y',`${(e.clientY-r.top-r.height/2)*.045}px`)});b.addEventListener('pointerleave',()=>{b.style.setProperty('--mag-x','0px');b.style.setProperty('--mag-y','0px')})})}
const revealObserver=motionOK&&'IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target)}}),{threshold:.14}):null;document.querySelectorAll('.steps article,.section-heading,.hero-copy').forEach(el=>{el.classList.add('reveal');if(revealObserver)revealObserver.observe(el);else el.classList.add('revealed')});
