function applyTheme(next){document.body.classList.add('theme-switching');theme=next;document.body.classList.toggle('light',theme==='light');$('#theme').textContent=theme==='light'?'☾':'☼';localStorage.setItem('js-theme',theme);setTimeout(()=>document.body.classList.remove('theme-switching'),340)}
