$('#profile-form').onsubmit=async e=>{e.preventDefault();const btn=$('#profile-save'),error=$('#profile-error');error.textContent='';const data={first_name:$('#profile-first').value.trim(),last_name:$('#profile-last').value.trim(),language:$('#profile-language').value,theme:$('#profile-theme').value};if(data.first_name.length>60||data.last_name.length>60){error.textContent='Names must be 60 characters or fewer.';return}btn.disabled=true;btn.classList.add('is-loading');try{profileData=await api('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});updateProfileIdentity();language=data.language;localStorage.setItem('js-lang',language);applyTheme(data.theme);$('#language').value=language;translate();showToast(words[language].saved);closeModal('profile-modal')}catch(err){error.textContent=err.message}finally{btn.disabled=false;btn.classList.remove('is-loading')}};
function setView(name){view=name;typeMode='all';$$('.side-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={history:words[language].history,pdfs:words[language].myPdfs,chat:words[language].askJan};$('#view-title').textContent=titles[name];$('#view-crumb').textContent=titles[name].toUpperCase();renderView()}
